import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Entities;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Element_siblingElements_TriageGen2Test {

    @Test
    public void testSiblingElementsWhenParentHasMultipleChildren() {
        String html = "<div><p>First</p><p>Second</p><p>Third</p></div>";
        Element div = Jsoup.parse(html).select("div").first();
        Element secondP = div.select("p").get(1);

        Elements siblings = secondP.siblingElements();
        assertEquals(2, siblings.size());
        assertTrue(siblings.contains(div.select("p").get(0)));
        assertTrue(siblings.contains(div.select("p").get(2)));
    }












}

